SELECT COUNT(*)
FROM sys_user
WHERE username = #{username}
  AND is_deleted = 0

    AND id != #{excludeId}

SELECT password_hash
FROM sys_user_password_history
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{historyCount}

SELECT COUNT(*)
FROM sys_user_role
WHERE user_id = #{userId}
  AND role_id = #{roleId}
  AND is_deleted = 0

SELECT COUNT(*)
FROM sys_user_dept
WHERE user_id = #{userId}
  AND dept_id = #{deptId}
  AND is_deleted = 0

mapper.update:
UPDATE sys_user_dept
SET is_primary = CASE WHEN dept_id = #{deptId} THEN 1 ELSE 0 END
WHERE user_id = #{userId}
